# owner: platform
"""Contact sheet for substitute teachers."""

from typing import Iterable, List, Sequence

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: Sequence[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for student in students:
        if not student.email:
            raise ProjectError(
                f"no email for {student.display_name}"
            )


def _align(rows: List[tuple]) -> List[str]:
    widths = [max(map(len, col)) for col in zip(*rows)]
    return [
        "  ".join(c.ljust(w) for c, w in zip(r, widths)).rstrip()
        for r in rows
    ]


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    people = sorted(students, key=_sort_key)
    _check(people)
    return _align(
        [(s.display_name, s.section, s.email) for s in people]
    )


def _sort_key(student: Student) -> tuple:
    return (student.display_name.casefold(), student.student_id)
